<?php session_start();require __DIR__.'/config.php';$mode=$_GET['mode']??'login';$next=$_GET['next']??'order.php';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$mode=$_POST['mode'];$next=$_POST['next']??'order.php';$u=trim($_POST['username']??'');$p=$_POST['password']??'';if($mode==='register'){ $n=trim($_POST['name']??'');if(!$n||!$u||strlen($p)<6)$message='Completa los datos. Mínimo 6 caracteres.';else try{$s=db()->prepare('INSERT INTO users(name,username,password_hash) VALUES(?,?,?)');$s->execute([$n,$u,password_hash($p,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>db()->lastInsertId(),'name'=>$n,'username'=>$u];header('Location: '.($next==='account.php'?'account.php':'order.php'));exit;}catch(Throwable $e){$message='Ese usuario ya existe.';}}else{$s=db()->prepare("SELECT * FROM users WHERE username=? AND role='customer'");$s->execute([$u]);$x=$s->fetch();if($x&&password_verify($p,$x['password_hash'])){$_SESSION['user']=['id'=>$x['id'],'name'=>$x['name'],'username'=>$x['username']];header('Location: '.($next==='account.php'?'account.php':'order.php'));exit;}$message='Usuario o contraseña incorrectos.';}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi cuenta | Milkito</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">M</span><span>adoquines <b>milkito</b></span></a><a class="admin-link" href="index.php">← Página principal</a></header><main class="order-section" style="min-height:calc(100vh - 80px)"><div class="order-intro"><p class="eyebrow">ANTES DE CONFIRMAR</p><h2><?=$mode==='register'?'Crea tu cuenta.':'Inicia sesión.'?></h2><p>Necesitamos tus datos para coordinar el delivery.</p></div><form class="order-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="mode" value="<?=e($mode)?>"><input type="hidden" name="next" value="<?=e($next)?>"><?php if($mode==='register'): ?><label>Nombre completo<input name="name" required></label><?php endif; ?><label>Usuario<input name="username" required></label><label>Contraseña<input type="password" name="password" required></label><?php if($message): ?><p style="color:#c94b38"><?=e($message)?></p><?php endif; ?><button class="btn btn-coral" type="submit"><?=$mode==='register'?'Crear cuenta':'Ingresar'?> →</button><p style="font-size:13px;margin-top:18px"><?php if($mode==='register'): ?>¿Ya tienes cuenta? <a href="auth.php?mode=login">Inicia sesión</a><?php else: ?>¿Nuevo en Milkito? <a href="auth.php?mode=register">Crea una cuenta</a><?php endif; ?></p></form></main></body></html>
